        p.f0 = Math.random() * 0.55; p.off = (Math.random() - 0.5) * 14;
        p.v = (ARM_SPEED * (0.7 + Math.random() * 0.5)) / ARM_LEN;
        p.life = 1.1 + Math.random() * 1.4; p.size = 0.8 + Math.random() * 0.7;
