          for (let j = 1; j <= 4; j++){
            const [tx, ty] = pos(Math.max(0, a - j * 0.035), t - j * 0.035);
            ctx.globalAlpha = 0.22 * al * (1 - j / 5); ctx.beginPath(); ctx.arc(tx, ty, p.size * (1.5 - j * 0.18), 0, TAU); ctx.fill();
          }
